SELECT
 MT.BOOKINGS_MEASURE_KEY,
 MT.BKGS_MEASURE_TRANS_TYPE_CODE,
 MT.BOOKINGS_PROCESS_DATE,
 MT.SALES_TERRITORY_KEY,
 MT.SALES_REP_NUMBER,
 MT.DV_CONTRACT_DURATION,
 MT.DV_ANNUALIZED_FLG,
 MT.RU_SERVICE_CONTRACT_START_DTM,
 MT.RU_SERVICE_CONTRACT_END_DTM,
 MT.ANNUITY_TYPE ANNUITY_TYPE,
RWK.FISCAL_YEAR_ANNV_WEEK_NUM_INT ANNUITY_WEEK,
 MT.DV_MULTIYEAR_US_NET_AMT  ANNUITY_AMT,
 MT.DV_FMV_FLG,
 MT.ADJUSTMENT_CODE
  FROM
 {{ source('raw', 'WI_MT_RSTD_BKGS_MEASURE_PRDT') }} MT
  INNER JOIN
  {{ source('raw', 'R_FISCAL_WEEK_TO_YEAR') }} RWK
ON RWK.FISCAL_YEAR_WEEK_NUM_INT = MT.BOOKINGS_PROCESS_WEEK
WHERE
 COLLATE( ANNUITY_TYPE, 'en-ci-rtrim') = 'UNKNOWN'